import urllib.request, re
from html.parser import HTMLParser

base = 'http://127.0.0.1:8765/out/'

class LinkChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.stylesheets = []
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == 'a' and 'href' in attrs:
            self.links.append(attrs['href'])
        if tag == 'link' and attrs.get('rel') == 'stylesheet':
            self.stylesheets.append(attrs.get('href', ''))

pages = ['index.html', 'about.html', 'posts/kettle-logic.html', 'posts/the-last-mile.html', 'posts/two-clocks.html']
all_ok = True
for page in pages:
    url = base + page
    try:
        html = urllib.request.urlopen(url).read().decode()
    except Exception as e:
        print(f'FAIL {page}: {e}')
        all_ok = False
        continue
    checker = LinkChecker()
    checker.feed(html)
    print(f'--- {page} ---')
    print(f'  stylesheets: {checker.stylesheets}')
    print(f'  links: {checker.links}')
    # Check each link resolves
    for href in checker.links:
        if href.startswith('http'):
            continue
        # Resolve relative to page directory
        if page.startswith('posts/'):
            resolved = base + 'posts/' + href
        else:
            resolved = base + href
        try:
            code = urllib.request.urlopen(resolved).getcode()
            if code != 200:
                print(f'  BROKEN: {href} -> {code}')
                all_ok = False
        except Exception as e:
            print(f'  BROKEN: {href} -> {e}')
            all_ok = False
    # Check stylesheet resolves
    for href in checker.stylesheets:
