            continue
        if page.startswith('posts/'):
            resolved = base + 'posts/' + href
        else:
            resolved = base + href
        try:
            code = urllib.request.urlopen(resolved).getcode()
            if code != 200:
                print(f'  BROKEN CSS: {href} -> {code}')
                all_ok = False
        except Exception as e:
            print(f'  BROKEN CSS: {href} -> {e}')
            all_ok = False

print()
print('ALL OK' if all_ok else 'FAILURES FOUND')
